import { Label as RadixLabel } from '@radix-ui/react-dropdown-menu';
import React, { forwardRef } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DOMProps } from '../../core/types/dom.js';
import type { WithChildren } from '../../core/types/with-children.js';

export const StyledLabel = /* @__PURE__ */ styled(RadixLabel)({
  boxSizing: 'border-box',

  fontFamily: Typography.Text.Small.Default.Family,
  fontSize: Typography.Text.Small.Default.Size,
  lineHeight: Typography.Text.Small.Default.LineHeight,
  fontWeight: Typography.Text.Small.Default.Weight,
  color: Colors.Text.Neutral.Subdued,

  paddingTop: Spacings.Size12,
  paddingBottom: Spacings.Size4,
  paddingLeft: Spacings.Size12,
  paddingRight: Spacings.Size12,

  textAlign: 'left',
});

export interface MenuLabelProps
  extends WithChildren,
    AriaLabelingProps,
    DOMProps {}

/**
 * Used to render a label. It won't be focusable using arrow keys.
 */
export const Label = /* @__PURE__ */ forwardRef<HTMLDivElement, MenuLabelProps>(
  (
    {
      children,
      id,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      'aria-details': ariaDetails,
    },
    forwardedRef,
  ) => (
    <StyledLabel
      ref={forwardedRef}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      aria-describedby={ariaDescribedBy}
      aria-details={ariaDetails}
      id={id}
    >
      {children}
    </StyledLabel>
  ),
);

(Label as typeof Label & { displayName: string }).displayName = 'Menu.Label';
